/**
 * Ambient declarations for the plugin build.
 *
 * - `*.css` imports are bundled as text by esbuild (`loader: { '.css': 'text' }`)
 *   and injected by the plugin itself.
 * - `dsh-pdf-assets` is generated by build.mjs from the installed pdfjs-dist
 *   package: the worker source and the same-version base64 data files.
 * - The DSH module loader's `require.async` loads package-local lazy chunks.
 */

interface NodeRequire {
  async(specifier: string): Promise<unknown>
}

declare module '*.css' {
  const text: string
  export default text
}

declare module 'dsh-pdf-assets' {
  export const workerSource: string
  export const pdfAssets: {
    readonly cMapUrl: Readonly<Record<string, string>>
    readonly standardFontDataUrl: Readonly<Record<string, string>>
    readonly wasmUrl: Readonly<Record<string, string>>
  }
}

/** The few host primitives this plugin renders; the real module ships with the shell. */
declare module '@deepseek-ai/dsh-client-ui-primitives' {
  import type { ComponentType } from 'react'
  export const FileTypeIcon: ComponentType<{
    readonly size?: number
    readonly className?: string
    readonly path?: string
    readonly kind?: string
  }>
}
